\begin{abstract}
We study a variational problem for the Landau--Lifshitz energy with Dzyaloshinskii--Moriya interactions arising in 2D micromagnetics, focusing on the Bogomol'nyi regime. We first determine the minimal energy for arbitrary topological degree, thereby revealing two types of phase transitions consistent with physical observations. In addition, we prove the uniqueness of the energy minimizer in degrees $0$ and $-1$, and nonexistence of minimizers for all other degrees. Finally, we show that the homogeneous state remains stable even beyond the threshold at which the skyrmion loses stability, and we uncover a new stability transition driven by the Zeeman energy.
\end{abstract}


\maketitle

\label{sec:minimal_energy}

In this section we prove Theorem \ref{thm:main1_energy_formula}, dividing the statement into three propositions (Propositions \ref{P2}, \ref{P4}, and \ref{P6}).
We first address the bounded-energy regime $0<r\leq1$ with negative degree (Proposition \ref{P2}), then nonnegative degree (Proposition \ref{P4}), and finally the unbounded-energy regime $r>1$ (Proposiion \ref{P6}).

\label{sec:rigidity}

In this section we prove the rigidity of minimizers in Theorem \ref{thm:main4_rigidity}.
We begin with a basic characterization in the non-endpoint case.

\begin{lemma}\label{lem:minimizer_necessary}
    Let $0<r<1$, $k\in\Z$, and $\bn\in\boM_k$.
    Then $\bn$ is a minimizer of $E_r$ in $\boM_k$ if and only if $\bn$ satisfies
    \begin{align*}
    |\boD^r_1\bn + \bn\times \boD^r_2\bn| = 0 \qquad \text{and} \qquad
    D[\bn] = 4\pi|Q[\bn]|.
    \end{align*}
\end{lemma}

\begin{proof}
    Using \eqref{e1.1} and \eqref{e1.2} we have
    \begin{align*}
    E_r[\bn] &= \frac {r^2}2 \int_{\R^2} |D^r_1\bn + \bn\times D^r_2\bn|^2 dx 
    + 4\pi r^2k + (1-r^2)D[\bn]\\
    &\ge 4\pi r^2k + (1-r^2)D[\bn]\\
    &\ge 4\pi r^2k + 4\pi(1-r^2)|Q[\bn]|,
    \end{align*}
    where the last term agrees with the minimal energy computed in Theorem \ref{thm:main1_energy_formula}.
    Hence $\bn$ is a minimizer if and only if the two 
    inequalities in the middle become equality, yielding the desired identities.
\end{proof}

The equation $|\boD^r_1\bn + \bn\times \boD^r_2\bn| = 0$ is often called the \emph{Bogomol'nyi equation}.

\label{sec:stability}

In this section, we analyze the stability of the homogeneous state $\bn = \boe_3$ for the energy functional $E_{r,h}$ in \eqref{eq:E_rh}.
By \eqref{eq:1124_02} we have
\begin{equation}\label{eq:ZL^2}
	Z[\bn] = \int_{\R^2}(1-n_3) dx = \frac12 \int_{\R^2}|\bn-\boe_3|^2 dx.
\end{equation}  

Recall that, when $h \neq 0$, the natural space for $E_{r,h}$ is $\boM'$ in \eqref{eq:space_M'}, which is a proper subset of $\boM$. 















We proceed to the stability analysis: first the critical $h=0$, then supercritical $h>0$, and finally subcritical case $h<0$.

In order to address the stability in the critical case $h=0$, we adopt a direct variational approach. We estimate the total energy of configurations that are close to $\boe_3$ with respect to the $L^2$-norm, and show that any $L^2$-perturbation leads to a strict increase in energy.

\begin{proof}[Proof of Theorem~\ref{thm:main2_stability}]
Let us write $\bn = \boe_3 + \bphi$. A straightforward computation yields
\begin{equation}\label{energydifference*}
E_r[\bn] - E_r[\boe_3] = 
\frac 12 \int_{\R^2} |\nab \bphi|^2 dx 
+ r\int_{\R^2} \bphi \cdot \nab \times \bphi dx 
+ \frac 18 \int_{\R^2} |\bphi|^4 dx.
\end{equation}
Note that
\begin{equation}\label{eq:phi_3}
1= |\bn|^2 = \phi_1^2 + \phi_2^2 + (1+\phi_3)^2 \quad
\Longleftrightarrow
\quad
\phi_3 = -\frac 12 |\bphi|^2.
\end{equation}
Then
\begin{align}
r \left| \int_{\R^2} \bphi \cdot \nab \times \bphi dx\right| 
&\stackrel{\eqref{eq:H_int_by_parts}}{=} 2
r \left|\int_{\R^2} \phi_3 (\rd_1 \phi_2 - \rd_2 \phi_1) dx\right| \notag\\
&\le 2
r \nor{\phi_3}{L^2} \nor{\rd_1 \phi_2 - \rd_2 \phi_1}{L^2}\notag \\
&\stackrel{\eqref{eq:phi_3}}{\le}
2r \nor{\frac 12 |\bphi|^2}{L^2} \nor{\nab \bphi}{L^2} \notag \\
&=
r \nor{\bphi}{L^4}^2 \nor{\nab \bphi}{L^2}\label{ineq:phi}\\
&\stackrel{\eqref{eq:Ladyzhenskaya}}{\le} Cr \nor{\bphi}{L^2} \nor{\nab \bphi}{L^2}^2.\notag
\end{align}
Inserting this estimate into \eqref{energydifference*}, we obtain
\begin{align*}
E_r [\bn] - E_r[\boe_3] \geq \left(\frac{1}{2}-Cr\nor{\bphi}{L^2}\right)\int_{\R^2} |\nab \bphi|^2 dx +\frac18\int_{\R^2} |\bphi|^4 dx.
\end{align*}
Now, if we take $\delta=\frac1{4Cr}$, the assumption $\nor{\bn-\boe_3}{L^2}=\nor{\bphi}{L^2}\leq\delta$ yields
\begin{align*}
E_r [\bn] - E_r[\boe_3] \geq \frac{1}{4}\nor{\nabla(\bn-\boe_3)}{L^2}^2 + \frac{1}{8}\nor{\bn-\boe_3}{L^4}^4,
\end{align*}
which implies the desired strict local minimality of $\bn=\boe_3$.
\end{proof}

\label{sec:couterexample_endpoint}

Here we rigorously verify that substantially new minimizers emerge in the endpoint case $r=1$, in stark contrast to the case $0<r<1$ treated in Section \ref{sec:rigidity}.
In particular, they give counterexamples to the uniqueness for degrees $Q=0,-1$ and also the nonexistence for $Q\geq1$ in Theorem \ref{thm:main4_rigidity}.
We stress that the non-uniqueness in this context means that two maps in $\boM$ do not agree even up to the natural invariances; translations and rotations in the domain, and horizontal rotations in the codomain.
Most of the arguments are strongly inspired by the complex analytic approach developed in \cite{MR4091507}.

We first observe that the same computation as in Lemma \ref{lem:minimizer_necessary} yields the following characterization, the proof of which can be safely omitted.

\begin{lemma}\label{lem:minimality_Bog_r=1}
    Let $k\in\Z$ and $\bn\in\boM_k$.
    Then $\bn$ is a minimizer of $E_1$ in $\boM_k$ if and only if 
    \begin{equation}\label{eq:Bogomol'nyi}
    |\boD^1_1 \bn + \bn\times \boD^1_2 \bn| =0.
    \end{equation}
\end{lemma}

In addition, if we let $v= \frac{1+n_3}{n_1+in_2}$ with variable $z=x_1+ix_2$ as in Section \ref{sec:rigidity}, then a family of a.e.\ solutions to the Bogomol'nyi equation \eqref{eq:Bogomol'nyi} is given by \eqref{familysol} with meromorphic $f$, as discovered in \cite{MR4091507}.
Recall that if $v$ is smooth up to isolated singularities, then so is the resulting map $\bn$, see \eqref{eq:v_to_n}.
Therefore, inserting any nontrivial meromorphic function $f$ into \eqref{familysol} yields a new minimizer, whenever $\bn$ has the integrability $D[\bn]+V[\bn]<\infty$.
Note that the integrands of $D$ and $V$ are re-expressed as
\begin{align}\label{eq:integrands_v}
\frac 12|\nab \bn|^2 = \frac{2|\nab v|^2}{(1+|v|^2)^2}, \qquad 
\frac 12 (1-n_3)^2 =  \frac{2}{(1+|v|^2)^2}.
\end{align}

In what follows, we consider a special class of meromorphic $f$, namely $f(z)=az^{k}$ with $k\in\Z$ and $a\in\C$, as well as the associated map as in \eqref{eq:v_to_n}, i.e.,
\begin{equation}\label{eq:general_formula_n_and_v_for_f=az^k}
    \bn^a=\left(\frac{2\Re(v)}{|v|^2+1},\frac{-2\Im(v)}{|v|^2+1},\frac{|v|^2-1}{|v|^2+1}\right), \qquad v \colonequals -\frac{i}{2}\overline{z} + az^{k}.
\end{equation}
Note that the power $k$ of $f$ will be strongly related to the topological degree of $\bn^a$, but generally they do not agree exactly.

One may generate other examples by considering general meromorphic functions, which is omitted in the present argument. Readers interested in this direction can refer to \cite{MR4091507}.

As observed in \cite{MR4091507}, the integrability issue is more delicate when the meromorphic function $f$ has linear growth at infinity.
Therefore, we first address the delicate case $k=1$, i.e., $f(z)= az$ with $a=a_1+ia_2\in\C$. 
Then $v$ in \eqref{eq:general_formula_n_and_v_for_f=az^k} can be written as 
\begin{align*} 
v= X_1^a + iX_2^a,&& X^a = 
\begin{pmatrix} 
X_1^a \\
X_2^a 
\end{pmatrix} 
= 
\begin{pmatrix} 
a_1 & -\frac12-a_2 \\ 
-\frac12+a_2 & a_1 
\end{pmatrix} 
\begin{pmatrix} 
x_1 \\
x_2 
\end{pmatrix},
\end{align*} 
and the associated map $\bn^a$ can be expressed by the \emph{distorted skyrmion} (cf.\ \cite{MR4091507}) 
\begin{align}\label{eq:n^a_k=1}
\bn^a = \left( \frac{2X_1^a}{|X^a|^2+1}, \frac{-2X_2^a}{|X^a|^2+1}, \frac{|X^a|^2-1}{|X^a|^2+1} \right). 
\end{align} 
Note that the $a=0$ case corresponds to the standard skyrmion $\bh^1$, while for $a\neq0$ the map $\bn^a$ is clearly distinct from $\bh^1$ as the domain coordinates are linearly distorted. 
In particular, the anti-skyrmion $\tilde{\bh}^1$ can formally be approached by $\bn^{a}(\frac{x}{|a|})$ with $a=(a_1,0)$ as $a_1\to-\infty$. 

These maps $\bn^a$ provide new minimizers for degrees $Q=\pm1$.

\begin{proposition}
    Let $a\in\C$ and $\bn^a$ be the map defined in \eqref{eq:n^a_k=1}.
    If $|a|<\frac12$, then $\bn^a\in \boM_{-1}$, and if $|a|>\frac12$, then $\bn^a\in \boM_{1}$.
    In particular, all members of the family $\{\bn^a\}_{|a|<\frac12}$ (resp.\ $\{\bn^a\}_{|a|>\frac12}$) are minimizers of $E_1$ in $\boM_{-1}$ (resp.\ $\boM_1$).
\end{proposition}


\begin{proof}
Since 
$|\nab v|^2 = 2(|\rd_z v|^2+ |\rd_{\ovl z} v|^2)=2|a|^2 + \frac 12$, 


the integrands in \eqref{eq:integrands_v} are given by
\begin{align*}
\frac{2|\nab v|^2}{(1+|v|^2)^2} 
= \frac{4|a|^2+1}{(1+|X^a|^2)^2}, \qquad \frac{2}{(1+|v|^2)^2}
=
 \frac{2}{(1+|X^a|^2)^2}.
\end{align*}
The transformation $x\mapsto X^a$ is linear with $\det\frac{\rd X^a}{\rd x}=|a|^2-\frac{1}{4}\neq0$ (since $|a|\neq\tfrac12$).
Hence these terms are integrable in $x$ if and only if they are integrable in $X^a$, implying that $\bn^a\in\boM$.

Moreover, direct computation gives 
\begin{align*}
Q[\bn^a]
=
\int_{\R^2} \frac{1}{\pi} 
\frac{|\rd_z v|^2 - |\rd_{\ovl z}v|^2}{(1+|v|^2)^2}dx
&=
\int_{\R^2} \frac{1}{4\pi}\frac{4|a|^2-1}{(1+|X^a|^2)^2}dx.
\end{align*}
Using $dx=|\det(\rd X^a/\rd x)|^{-1}
=\frac{4}{|4|a|^2-1|}$, we obtain
\begin{align*}
Q[\bn^a]
&=
\frac{4|a|^2-1}{|4|a|^2-1|}
\int_{\R^2}\frac{1}{\pi}\frac{1}{(1+|X^a|^2)^2}dX^a
=
\begin{cases}
    -1 & (|a|<\frac12),\\
    1 & (|a|>\frac12).
\end{cases}
\end{align*}
Since the minimality of $\bn^a$ follows from Lemma \ref{lem:minimality_Bog_r=1}, the proof is complete.
\end{proof}

In this special case, the geometry of the sets $Z_0$ and $Z_1$ is rather simple.
Let $a=a_1+ia_2\neq0$.
By \eqref{eq:v_formula} we have $z\in Z_0$ if and only if $2a=i|z|^2$.
Hence
\begin{align*}
    Z_0=
    \begin{cases}
       \{ |z|^2=2a_2 \} & (a_1=0,\ a_2>0),\\
       \emptyset & (\text{otherwise}).
    \end{cases}
\end{align*}
By \eqref{eq:|v|^2_formula} we have $z\in Z_1$ if and only if $\frac{1}{4}|z|^4-(\Im{a}+1)|z|^2+|a|^2=0$.
Solving the equation yields
\begin{align*}
    Z_1=
    \begin{cases}
       \big\{ |z|^2=2 ( a_2+1 \pm \sqrt{2a_2+1-a_1^2} ) \big\} & (a_2>\frac{1}{2}a_1^2-\frac{1}{2}),\\
       \{ |z|^2=2(a_2+1) \} & (a_2=\frac{1}{2}a_1^2-\frac{1}{2}),\\
       \emptyset & (a_2<\frac{1}{2}a_1^2-\frac{1}{2}).
    \end{cases}
\end{align*}
Thus the set $Z_0\cup Z_1$ consists of at most three concentric circles.
In particular, if the circle $Z_0$ is present, then $Z_1$ always has two circles surrounding $Z_0$.

